package com.example;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

class CalculatorTest {
    @Test
    void addsTwoNumbers() { // Package-private is idiomatic in JUnit 5!
        assertEquals(4, 2 + 2);
    }
}

@Test
void validateUser() {
    User user = new User("Alice", "Smith", 30);

    assertAll("user verification",
        () -> assertEquals("Alice", user.getFirstName()),
        () -> assertEquals("Smith", user.getLastName()),
        () -> assertEquals(30, user.getAge())
    );
}

@Test
void throwsOnNegativeDeposit() {
    Account account = new Account();

    IllegalArgumentException ex = assertThrows(IllegalArgumentException.class, () -> {
        account.deposit(BigDecimal.valueOf(-50));
    });

    assertEquals("Deposit cannot be negative", ex.getMessage());
}

